import React from "react";
import { useQuery } from '@tanstack/react-query';


function child(){
  const {data, isPending, isError, error} = useQuery({
    queryKey: ['posts'],
    queryFn: fetchData,
  })
  if (isPending) {
    return <p>Loading.....</p>
  }
  if (isError) {
    return <p>Error: {error.message}</p>;
  }

  return (
    <div className="App">
      <ul>
        {data.map((post) => (
          <li key={post.id}>{post.title}</li>
        ))}
      </ul>
    </div>
  );
}
export default child
